{
  "name": "@aihot/api",
  "private": true,
  "type": "module",
  "exports": {
    "./*": "./src/*.ts"
  },
  "scripts": {
    "dev": "node --watch --env-file-if-exists=../../.env src/main.ts",
    "start": "node src/main.ts"
  },
  "dependencies": {
    "@aihot/backend": "*",
    "@aihot/contracts": "*",
    "@aihot/industry": "*",
    "@aihot/site": "*",
    "@modelcontextprotocol/server": "2.1.0",
    "fastify": "5.12.5",
    "zod": "4.6.5"
  }
}

// Admin sign-in and the /api/admin guard. Public routes never read the session.
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { ZodError } from "zod";
import type { AdminMe } from "@aihot/contracts/admin";
import { DEPLOYMENT, SITE } from "@aihot/site";
import { config } from "@aihot/backend/config";
import {
  completeLogin,
  cookie,
  endSession,
  feishuLoginConfigured,
  LoginRejected,
  loginRedirect,
  parseCookies,
  passwordLogin,
  safeReturn,
  SESSION_COOKIE,
  SESSION_DAYS,
  sessionPrincipal,
  STATE_COOKIE,
  type AdminPrincipal,
} from "@aihot/backend/admin/auth";
import { sendProblem } from "../http/respond.ts";

/** Cookies are Secure whenever the site is served over HTTPS. */
const secure = () => config.siteUrl.startsWith("https://");

/**
 * Password attempts: at most 10 per client address and 50 in all per 15 minutes. The overall cap holds
 * even when a client forges its address; with a 12+ character password that is far too slow to guess.
 */
const attempts = new Map<string, number[]>();
function over(key: string, limit: number, now: number): boolean {
  const recent = (attempts.get(key) ?? []).filter((t) => now - t < 15 * 60_000);
  recent.push(now);
  attempts.set(key, recent);
  return recent.length > limit;
}
function tooManyAttempts(ip: string): boolean {
  const now = Date.now();
  if (attempts.size > 5000) attempts.clear();
  const perClient = over(`ip:${ip}`, 10, now);
  return over("all", 50, now) || perClient;
}

const loginPage = (returnTo: string, error?: string) => `/admin/login?${new URLSearchParams({ return: safeReturn(returnTo), ...(error ? { error } : {}) })}`;

export type AdminHandler = (req: FastifyRequest, reply: FastifyReply, admin: AdminPrincipal) => Promise<unknown>;

/** Guard for /api/admin/*: a live session (or the development stand-in); writes need the CSRF token. */
export function adminHandler(fn: AdminHandler) {
  return async (req: FastifyRequest, reply: FastifyReply) => {
    reply.header("Cache-Control", "no-store");
    const admin = await sessionPrincipal(req.headers.cookie);
    if (!admin) return sendProblem(req, reply, { status: 401, code: "unauthorized", detail: "Sign in to the admin first." });
    if (req.method !== "GET" && req.method !== "HEAD" && req.headers["x-csrf-token"] !== admin.csrf) {
      return sendProblem(req, reply, { status: 403, code: "forbidden", detail: "Missing or stale CSRF token." });
    }
    try {
      return await fn(req, reply, admin);
    } catch (error) {
      if (error instanceof ZodError) {
        return sendProblem(req, reply, { status: 400, code: "invalid_request", detail: error.issues.map((issue) => `${issue.path.join(".") || "请求"}: ${issue.message}`).join("; ").slice(0, 300) });
      }
      if ((error as { statusCode?: number }).statusCode === 400 || error instanceof SyntaxError) {
        return sendProblem(req, reply, { status: 400, code: "invalid_request", detail: String((error as Error).message).slice(0, 300) });
      }
      if ((error as { code?: string }).code === "conflict") return sendProblem(req, reply, { status: 409, code: "conflict", detail: (error as Error).message });
      req.log.error({ err: error, path: req.url.split("?")[0] }, "admin api error");
      return sendProblem(req, reply, { status: 500, code: "internal_error", detail: String((error as Error).message).slice(0, 300) });
    }
  };
}

/** Feishu sign-in: the state cookie, then Feishu's authorization page. */
function feishuRedirect(reply: FastifyReply, returnTo: string) {
  const { url, stateCookie } = loginRedirect(returnTo);
  reply.header("Set-Cookie", cookie(STATE_COOKIE, stateCookie, 600, secure())).header("Cache-Control", "no-store");
  return reply.redirect(url, 302);
}

export function registerAdminAuth(app: FastifyInstance) {
  // The web admin sends a signed-out visitor here with ?return=, a reverse proxy with the site's header.
  // With Feishu as the only way in, sign-in starts there at once; otherwise the sign-in page (in the web
  // app) offers the ways in.
  app.get("/api/auth/login", async (req, reply) => {
    const returnTo = String(
      (req.query as Record<string, string>).return
      ?? (DEPLOYMENT.loginReturnHeader ? req.headers[DEPLOYMENT.loginReturnHeader.toLowerCase()] : undefined)
      ?? "/admin",
    );
    if (feishuLoginConfigured() && !config.adminPassword) return feishuRedirect(reply, returnTo);
    return reply.header("Cache-Control", "no-store").redirect(loginPage(returnTo), 302);
  });

  app.get("/api/auth/options", async (_req, reply) => reply.header("Cache-Control", "no-store").send({ password: !!config.adminPassword, feishu: feishuLoginConfigured() }));

  // The sign-in form posts as a plain HTML form; only this route reads that format.
  app.register(async (form) => {
    form.addContentTypeParser("application/x-www-form-urlencoded", { parseAs: "string", bodyLimit: 16 * 1024 }, (_req, body, done) => {
      done(null, Object.fromEntries(new URLSearchParams(String(body))));
    });
    form.post("/api/auth/password", async (req, reply) => {
      const b = (req.body ?? {}) as Record<string, string>;
      const returnTo = String(b.return ?? "/admin");
      reply.header("Cache-Control", "no-store");
      if (tooManyAttempts(String(req.ip))) return reply.redirect(loginPage(returnTo, "too-many"), 303);
      try {
        const { token, returnTo: target } = await passwordLogin(String(b.password ?? ""), returnTo, req.headers["user-agent"]);
        reply.header("Set-Cookie", cookie(SESSION_COOKIE, token, SESSION_DAYS * 86400, secure()));
        return reply.redirect(target, 303);
      } catch (error) {
        if (!(error instanceof LoginRejected)) req.log.error({ err: error }, "admin login failed");
        return reply.redirect(loginPage(returnTo, error instanceof LoginRejected && /ADMIN_PASSWORD/.test(error.message) ? "unset" : "wrong"), 303);
      }
    });
  });

  // Feishu sign-in (FEISHU_LOGIN_APP_ID / FEISHU_LOGIN_APP_SECRET and an allowlist), from the sign-in page.
  app.get("/api/auth/feishu", async (req, reply) => {
    const returnTo = String((req.query as Record<string, string>).return ?? "/admin");
    if (!feishuLoginConfigured()) return reply.header("Cache-Control", "no-store").redirect(loginPage(returnTo), 302);
    return feishuRedirect(reply, returnTo);
  });

  // The callback registered in the Feishu open platform: the state cookie comes back here.
  app.get("/api/auth/callback", async (req, reply) => {
    const q = req.query as Record<string, string>;
    reply.header("Cache-Control", "no-store");
    try {
      const { token, returnTo } = await completeLogin(String(q.code ?? ""), String(q.state ?? ""), parseCookies(req.headers.cookie)[STATE_COOKIE], req.headers["user-agent"]);
      reply.header("Set-Cookie", [cookie(SESSION_COOKIE, token, SESSION_DAYS * 86400, secure()), cookie(STATE_COOKIE, "", 0, secure())]);
      return reply.redirect(returnTo, 302);
    } catch (error) {
      const message = error instanceof LoginRejected ? error.message : "登录失败，请稍后再试";
      if (!(error instanceof LoginRejected)) req.log.error({ err: error }, "admin login failed");
      return reply.code(403).type("text/html; charset=utf-8").send(`<!doctype html><meta charset="utf-8"><title>登录失败 · ${SITE.name}</title><p style="font:16px system-ui;padding:40px">${message}。<a href="/api/auth/login">重新登录</a></p>`);
    }
  });

  // For a reverse proxy that guards /admin itself (auth_request): 204 with a live session, else 401.
  // Only the session cookie counts here, never the development stand-in.
  app.get("/api/auth/check", async (req, reply) => {
    reply.header("Cache-Control", "no-store");
    const admin = await sessionPrincipal(req.headers.cookie);
    return reply.code(admin && !admin.dev ? 204 : 401).send();
  });

  app.post("/api/auth/logout", async (req, reply) => {
    await endSession(req.headers.cookie);
    reply.header("Set-Cookie", cookie(SESSION_COOKIE, "", 0, secure())).header("Cache-Control", "no-store");
    return reply.redirect("/", 303);
  });

  app.get("/api/admin/me", adminHandler(async (_req, _reply, admin): Promise<AdminMe> => ({ name: admin.name, csrf: admin.csrf, dev: admin.dev })));
}

// Failure cases: two workers finish the same extraction; a report revises the article while a page
// or X Article is in flight; an obsolete empty response marks new input unconfirmed; an admin
// repeats extraction of unchanged HTML. Neither content nor revision history may go backwards.
import { gate, Reply, stub, tag } from "./setup.ts";
import assert from "node:assert/strict";
import http from "node:http";
import { after, before, test } from "node:test";
import { config } from "@aihot/backend/config";
import { closeDb, sql } from "@aihot/backend/db";
import { extractArticleBody } from "@aihot/backend/content/extract";
import { upsertMaterial } from "@aihot/backend/content/materials";
import { getBoss, stopBoss } from "@aihot/backend/jobs/queue";
import { queueProcessing, registerExtractionJobs } from "@aihot/backend/jobs/content";

const sourceId = `extract-consistency-${tag()}`;
const body = "This is the original article, with enough substantive text to extract its paragraphs. ".repeat(12);
let hold: { entered: ReturnType<typeof gate<void>>; release: ReturnType<typeof gate<void>>; count: number; empty: boolean; failed?: boolean };
const page = http.createServer(async (_req, res) => {
  if (--hold.count === 0) hold.entered.open();
  await hold.release.promise;
  res.writeHead(200, { "content-type": "text/html" });
  res.end(hold.empty ? "<html><body>Empty</body></html>" : `<html><head><title>Original</title></head><body><article><h1>Original</h1><p>${body}</p></article></body></html>`);
});
await new Promise<void>(resolve => page.listen(0, "127.0.0.1", resolve));
const base = `http://127.0.0.1:${(page.address() as { port: number }).port}`;
const socialdata = await stub(async () => {
  hold.entered.open();
  await hold.release.promise;
  if (hold.failed) return new Reply(503, { error: "Temporary extraction failure" });
  return hold.empty ? {} : { article: { title: "Old X Article", content_state: { blocks: [{ text: body }] } } };
});
process.env.SOCIALDATA_API_KEY = "test-key";
process.env.SOCIALDATA_BASE_URL = socialdata.url;
process.env.JINA_API_KEY = "test-key";
config.allowPrivateNetworkFetch = true;
before(async () => {
  await sql`INSERT INTO sources(id,name,kind) VALUES (${sourceId},'Extraction consistency','rss')`;
  await sql`UPDATE budgets SET per_minute=1000,per_hour=1000,per_day=1000 WHERE service='socialdata'`;
  // Jina stopped: a page without a readable body stays without one.
  await sql`UPDATE budgets SET per_minute=0,per_hour=0,per_day=0 WHERE service='jina'`;
});
after(async () => { page.close(); await socialdata.close(); await stopBoss(); await closeDb(); });
const reset = (count = 1, empty = false) => { hold = { entered: gate(), release: gate(), count, empty }; };
const state = async (id: string) => ({ ...(await sql`SELECT title,body_text,body_status,revision,content_hash FROM articles WHERE id=${id}`)[0] });

for (const x of [false, true]) for (const empty of [false, true]) {
  test(`a stale ${x ? "X Article" : "page"} ${empty ? "empty" : "successful"} response cannot change newer material`, async () => {
    reset(1, empty);
    const tweetId = `${Date.now()}${empty ? 2 : 1}`;
    const material = { sourceId, url: `${base}/${tag()}`, title: "Original", via: "fetch" as const,
      ...(x ? { xPost: { tweetId, authorName: "Author", handle: "author", text: "https://x.com/i/article/123" } } : {}) };
    const { articleId } = await upsertMaterial(material);
    const pending = extractArticleBody(articleId);
    await hold.entered.promise;
    let expected;
    try {
      await upsertMaterial({ ...material, title: "Corrected report", ...(empty ? {} : { bodyText: "The corrected body supplied by the publisher." }) });
      expected = await state(articleId);
    } finally { hold.release.open(); }
    const result = await pending;
    assert.deepEqual(await state(articleId), expected, "old network results must not touch the new revision or its pending status");
    assert.equal(result, "skipped");
  });
}

test("overlapping page extractions and an unchanged admin retry create only one body revision", async () => {
  reset(2);
  const { articleId } = await upsertMaterial({ sourceId, url: `${base}/${tag()}`, title: "Original", via: "fetch" });
  const pending = [extractArticleBody(articleId), extractArticleBody(articleId)];
  await hold.entered.promise;
  hold.release.open();
  await Promise.all(pending);
  const saved = await state(articleId);
  assert.equal(saved.revision, 2, "concurrent workers must not revise identical content twice");
  reset();
  hold.release.open();
  await sql`UPDATE articles SET body_status='pending' WHERE id=${articleId}`;
  assert.equal(await extractArticleBody(articleId), "ok");
  assert.deepEqual(await state(articleId), saved);
  assert.equal((await sql`SELECT 1 FROM article_revisions WHERE article_id=${articleId}`).length, 2);
});

// The worker's error path is also a write: a late provider error must not add retry state to a
// newer, complete report. Exercise pg-boss's actual callback rather than only the extractor.
test("an obsolete extraction failure cannot penalize a newer complete report", async () => {
  reset();
  hold.failed = true;
  const source = `${sourceId}-worker`;
  await sql`INSERT INTO sources(id,name,kind) VALUES (${source},'Extraction worker','x_search')`;
  const material = { sourceId: source, url: `https://x.com/author/status/${Date.now()}`, title: "Original", via: "fetch" as const,
    xPost: { tweetId: `${Date.now()}9`, authorName: "Author", handle: "author", text: "https://x.com/i/article/123" } };
  const { articleId } = await upsertMaterial(material);
  const job = await queueProcessing(articleId);
  await registerExtractionJobs(await getBoss());
  await hold.entered.promise;
  try { await upsertMaterial({ ...material, title: "Corrected", bodyText: "Complete corrected body" }); }
  finally { hold.release.open(); }
  const deadline = Date.now() + 12_000;
  while ((await sql`SELECT state FROM pgboss.job WHERE id=${job!}`)[0]?.state !== "completed") {
    assert.ok(Date.now() < deadline, "extraction worker did not finish");
    await new Promise(resolve => setTimeout(resolve, 20));
  }
  const [row] = await sql`SELECT body_status,processing_attempts,processing_error,processing_retry_at FROM articles WHERE id=${articleId}`;
  assert.deepEqual({ ...row }, { body_status: "ok", processing_attempts: 0, processing_error: null, processing_retry_at: null });
});

// An explicit full-text preference or the web-list kind must not bypass the video-page exclusion.
import { tag } from "./setup.ts";
import assert from "node:assert/strict";
import { after, test } from "node:test";
import { sql, closeDb } from "@aihot/backend/db";
import { upsertMaterial } from "@aihot/backend/content/materials";
import { queueProcessing } from "@aihot/backend/jobs/content";
import { QUEUES, stopBoss } from "@aihot/backend/jobs/queue";

const T = tag();
after(async () => { await stopBoss(); await closeDb(); });

test("RSS and web entries that point to videos skip body extraction even when full text was requested", async () => {
  for (const [kind, requested] of [["rss", false], ["rss", true], ["web_list", false]] as const) {
    const sourceId = `video-routing-${kind}-${requested}-${T}`;
    await sql`INSERT INTO sources(id,name,kind,config,tier,participation_mode) VALUES (${sourceId},'Video routing',${kind},${sql.json({ fetchPublicContent: requested })},'T1','editorial')`;
    const url = `https://www.youtube.com/watch?v=${kind}${requested}${T}`;
    const { articleId } = await upsertMaterial({ sourceId, url, title: "A video announcement", excerpt: "A publisher-supplied description.", bodyStatus: "pending", via: "fetch" });
    const jobId = await queueProcessing(articleId);
    const [job] = await sql<{ name: string }[]>`SELECT name FROM pgboss.job WHERE id=${jobId!}`;
    assert.equal(job!.name, QUEUES.analyze, `${kind} ${requested}`);
  }
});

// Shared setup for the invariant tests (node --test tests/). They write rows, so they refuse to run
// unless DATABASE_URL names a throwaway database ending in _test or _ci.
// Secrets are test values set here, never real credentials; paid providers are pointed at local stubs
// by the tests that need them, and the push valves stay off. npm test gives each database test file its own copy of
// the database (databases.ts).
import { createHash } from "node:crypto";
import http from "node:http";
import { beijingAt } from "@aihot/contracts/time";
import { EDITION_TIMES } from "@aihot/site";
import { DEFAULTS, PRESETS } from "@aihot/site/models";

const database = new URL(process.env.DATABASE_URL ?? "postgres://unset/unset").pathname.slice(1);
if (!/_(test|ci)$/.test(database)) {
  throw new Error(`Invariant tests write rows: point DATABASE_URL at a throwaway database named *_test or *_ci (got "${database}")`);
}
process.env.AIHOT_CREDENTIALS_DIR = "/nonexistent-test-credentials";
process.env.SESSION_SECRET ??= "test-session-secret-0123456789";
process.env.IMG_PROXY_SIGN_SECRET ??= "test-img-secret-0123456789";
process.env.FEISHU_CONTENT_PUSH_ENABLED = "false";
process.env.INDEXNOW_SUBMIT_ENABLED = "false";
process.env.LOG_LEVEL ??= "error";
// Paid providers are local stubs in these tests: calls and collection may run (the valves default off).
process.env.MODEL_CALLS_ENABLED ??= "true";
process.env.COLLECT_ENABLED ??= "true";
// The tests were written against named model presets, one per step (each provider is pointed at a
// local stub by the test that needs it). A step the site leaves on the `default` model gets its
// preset here; tests/default-model.test.ts covers the default.
const STEP_MODELS: Record<string, [env: string, model: string]> = {
  prefilter: ["PREFILTER_MODEL", "qwen3.7-flash"], score: ["SCORE_MODEL", "glm-5.3-flash-selection"], understand: ["UNDERSTAND_MODEL", "glm-5.3-flash"],
  summarize: ["SUMMARIZE_MODEL", "deepseek-flash"], structure: ["STRUCTURE_MODEL", "qwen3.8-flash"], group: ["GROUP_MODEL", "deepseek-flash"],
  groupReview: ["GROUP_REVIEW_MODEL", "mimo-v2.6-flash"], digest: ["DIGEST_MODEL", "deepseek-flash"], report: ["REPORT_MODEL", "deepseek-flash"],
  translate: ["TRANSLATE_MODEL", "deepseek-flash"],
};
for (const [step, [env, model]] of Object.entries(STEP_MODELS)) if (!DEFAULTS[step]) process.env[env] ??= model;

/**
 * Sends the calls of the named model presets to a stub: sets each one's address and key variables, which
 * the site's presets name. By default the providers of the article analysis (DashScope, GLM, DeepSeek).
 */
export function pointModels(url: string, models = ["qwen3.7-flash", "glm-5.3-flash", "deepseek-flash"], env: NodeJS.ProcessEnv = process.env) {
  for (const name of models) {
    const preset = PRESETS[name];
    if (!preset) throw new Error(`the site has no model preset ${name}`);
    env[preset.baseUrlEnv] = `${url}/v1`;
    env[preset.apiKeyEnv] = "test-key";
  }
}

/**
 * A local HTTP stub standing in for a paid provider; `answer` builds every response from the request
 * (it may wait, to hold a request open while a test changes something).
 */
export async function stub(answer: (hit: number, req: { url: string; body: string }) => unknown) {
  let hits = 0;
  const server = http.createServer((req, res) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", async () => {
      hits += 1;
      const out = await answer(hits, { url: req.url ?? "/", body: Buffer.concat(chunks).toString("utf8") });
      const reply = out instanceof Reply ? out : { status: 200, json: out };
      res.writeHead(reply.status, { "content-type": "application/json" });
      res.end(JSON.stringify(reply.json));
    });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", () => resolve()));
  const { port } = server.address() as { port: number };
  return { url: `http://127.0.0.1:${port}`, hits: () => hits, close: () => new Promise<void>((resolve) => server.close(() => resolve())) };
}

/**
 * The embeddings provider as a stub of its own (DASHSCOPE_BASE_URL), so chat stubs count only their
 * calls. A text's vector marks the pairs of adjacent characters it contains, hashed into the model's
 * 1,024 dimensions: texts that share wording come out close, texts that share none do not.
 */
export async function embeddingsStub() {
  const vector = (text: string) => {
    const out = Array<number>(1024).fill(0);
    const chars = [...text.replace(/\s+/g, "")];
    for (let i = 0; i + 1 < chars.length; i++) out[createHash("sha256").update(chars[i]! + chars[i + 1]!).digest().readUInt16BE(0) % 1024] = 1;
    return out;
  };
  const server = await stub((_hit, req) => ({ data: (JSON.parse(req.body).input as string[]).map((text, index) => ({ index, embedding: vector(text) })) }));
  process.env.DASHSCOPE_BASE_URL = `${server.url}/v1`;
  process.env.DASHSCOPE_API_KEY = "test-key";
  return server;
}

/** A stub answer with its own status (e.g. a provider's 503); anything else is a 200 JSON body. */
export class Reply {
  readonly status: number;
  readonly json: unknown;
  constructor(status: number, json: unknown) {
    this.status = status;
    this.json = json;
  }
}

/** A promise with its resolve function, to hold a stub's answer until a test releases it. */
export function gate<T = void>() {
  let open!: (value: T) => void;
  const promise = new Promise<T>((resolve) => (open = resolve));
  return { promise, open };
}

/** A short unique tag for the rows a test creates. */
export const tag = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;

/** `seconds` after the site's edition time of a report kind on a Beijing date (EDITION_TIMES), so tests follow the site's schedule. */
export const editionAt = (kind: keyof typeof EDITION_TIMES, date: string, seconds = 0) => new Date(beijingAt(date, EDITION_TIMES[kind]).getTime() + seconds * 1000);

// Which models a step may use (admin) and whether it is sent an image (runtime) read the same flag.
import "./setup.ts";
import assert from "node:assert/strict";
import { after, test } from "node:test";
import { closeDb } from "@aihot/backend/db";
import { modelsOverview, switchModel } from "@aihot/backend/admin/models";
import {
  CAPABILITIES,
  capabilityAcceptsModel,
  modelFor,
  modelSupportsVision,
} from "@aihot/backend/editorial/models";
import { MODELS } from "@aihot/backend/providers/llm";

after(closeDb);

test("every step takes a model that reads images; only a step that needs images refuses a text model", async () => {
  const understand = CAPABILITIES.understand;
  assert.equal(capabilityAcceptsModel(understand, MODELS["glm-5.3-flash"]!), true);
  assert.equal(capabilityAcceptsModel(understand, MODELS["qwen3-vl-flash"]!), true);
  assert.equal(capabilityAcceptsModel(understand, MODELS["deepseek-flash"]!), true);
  assert.equal(capabilityAcceptsModel(CAPABILITIES.score, MODELS["qwen3-vl-flash"]!), true);
  assert.equal(capabilityAcceptsModel({ ...understand, vision: true }, MODELS["deepseek-flash"]!), false);

  await switchModel("understand", "qwen3-vl-flash", "vision routing test", "test");
  assert.equal(await modelFor("understand"), "qwen3-vl-flash");
  await switchModel("understand", "deepseek-flash", "text routing test", "test");
  assert.equal(await modelFor("understand"), "deepseek-flash");

  const overview = await modelsOverview(1);
  assert.equal(overview.capabilities.find((capability) => capability.key === "understand")?.vision, false);
});

test("runtime image attachment is explicit rather than probing presets with unspecified vision support", () => {
  assert.equal(modelSupportsVision("qwen3-vl-flash"), true);
  assert.equal(modelSupportsVision("glm-5.3-flash"), true);
  assert.equal(modelSupportsVision("qwen3.8-flash"), false);
  assert.equal(modelSupportsVision("default"), process.env.LLM_VISION === "true");
});

import "./setup.ts";
import assert from "node:assert/strict";
import { test } from "node:test";
import Fastify from "fastify";
import { Client, StreamableHTTPClientTransport } from "@modelcontextprotocol/client";
import { MCP_TOOLS } from "@aihot/contracts/mcp";
import { registerMcp } from "../apps/api/src/routes/mcp.ts";

// The SDK advertises tools.listChanged unless told otherwise, and a 2026-07-28 client that handles list
// changes then keeps a listen stream open for its whole session: an idle connection per agent. A client
// that listens anyway gets the protocol's answer for a method the server does not implement, at once.
test("an MCP client opens no listen stream, and one that asks is refused at once", { timeout: 5000 }, async () => {
  const app = Fastify();
  const methods: string[] = [];
  app.addHook("onRequest", async (req) => { methods.push(String(req.headers["mcp-method"] ?? req.method)); });
  registerMcp(app);
  const address = await app.listen({ host: "127.0.0.1", port: 0 });
  const client = new Client({ name: "listen-check", version: "1.0.0" }, {
    listChanged: { tools: { onChanged: () => {} } },
    versionNegotiation: { mode: { pin: "2026-07-28" } },
  });
  try {
    await client.connect(new StreamableHTTPClientTransport(new URL(`${address}/api/mcp`)));
    assert.equal((await client.listTools()).tools.length, MCP_TOOLS.length);
    assert.equal(client.getServerCapabilities()?.tools?.listChanged, false);
    assert.equal(client.autoOpenedSubscription, undefined);
    assert.ok(!methods.includes("subscriptions/listen"), methods.join(","));

    await assert.rejects(client.listen({ toolsListChanged: true }));
    const response = await fetch(`${address}/api/mcp`, {
      method: "POST",
      headers: { "content-type": "application/json", accept: "application/json, text/event-stream", "mcp-protocol-version": "2026-07-28", "mcp-method": "subscriptions/listen" },
      body: JSON.stringify({ jsonrpc: "2.0", id: "listen-1", method: "subscriptions/listen", params: {
        _meta: { "io.modelcontextprotocol/protocolVersion": "2026-07-28", "io.modelcontextprotocol/clientCapabilities": {} },
        notifications: { toolsListChanged: true },
      } }),
    });
    assert.equal(response.status, 404);
    assert.deepEqual(await response.json(), { jsonrpc: "2.0", id: "listen-1", error: { code: -32601, message: "Method not found" } });
    assert.equal((await client.listTools()).tools.length, MCP_TOOLS.length, "ordinary calls are unaffected");
  } finally {
    await client.close();
    app.server.closeAllConnections();
    await app.close();
  }
});

