test('unrelated completed or rejected searches cannot displace an unfinished shared read', async () => {
  for (const failing of [false, true]) {
    const release = gate();
    let reads = 0;
    const search = sharedSearch((key: string) => key, async (key) => {
      if (key === 'held') { reads++; await release.promise; return key; }
      if (failing) throw new Error('invalid unrelated search');
      return key;
    }, () => true);
    const first = search('held');
    await Promise.allSettled(Array.from({ length: 250 }, (_, i) => search(`unrelated-${i}`)));
    const next = search('held');
    release.open();
    assert.deepEqual(await Promise.all([first, next]), ['held', 'held']);
    assert.equal(reads, 1, 'settled searches must not force an identical unfinished query to run twice');
  }
});

// A module can require arguments without an empty-site sample. Discovery is always checked, and
// declared samples remain real SDK calls: invalid arguments, failed reads and missing tools fail.
import "./setup.ts";
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { test } from "node:test";
import { promisify } from "node:util";
import Fastify from "fastify";
import { z } from "zod";
import { closeDb } from "@aihot/backend/db";
import { installModules, type AgentAbility } from "@aihot/backend/modules";
import { mcpToolName } from "@aihot/contracts/mcp";
import { registerMcp } from "../apps/api/src/routes/mcp.ts";

function asyncInput(acceptEmpty: boolean) {
  return z.strictObject({ id: z.string().optional() }).refine(async ({ id }) => acceptEmpty || id !== undefined);
}

test("the MCP check uses module samples and keeps its failure assertions", async (t) => {
  const calls: Record<string, unknown>[] = [];
  const abilities: AgentAbility[] = [
    {
      path: "/echo-check", title: "echo", ask: "echo", answer: async () => "echo", etagPrefix: "echo", cacheControl: "no-store",
      mcp: {
        tool: "echo_check", use: "for tests", description: "Echo a required label.",
        input: z.strictObject({ label: z.string().min(2) }), checkArgs: { label: "sample" },
        run: async (args) => {
          calls.push(args);
          if (args.label === "fail") throw new Error("fixture read failed");
          return { text: String(args.label), structured: { label: args.label } };
        },
      },
    },
    {
      path: "/status-check", title: "status", ask: "status", answer: async () => "ok", etagPrefix: "status", cacheControl: "no-store",
      mcp: {
        tool: "status_check", use: "for tests", description: "An async input accepting empty arguments.", input: asyncInput(true),
        run: async (args) => { calls.push(args); return { text: "ok", structured: { status: "ok" } }; },
      },
    },
    {
      path: "/async-check", title: "async", ask: "async", answer: async () => "ok", etagPrefix: "async", cacheControl: "no-store",
      mcp: {
        tool: "async_check", use: "for tests", description: "An async input requiring an id.", input: asyncInput(false),
        run: async (args) => { calls.push(args); return { text: "ok", structured: { id: args.id } }; },
      },
    },
  ];
  installModules([{ name: "check-fixture", agent: { abilities } }]);
  const app = Fastify();
  const requestedTools: string[] = [];
  app.addHook("preHandler", async (req) => {
    const body = req.body as { method?: string; params?: { name?: string } } | undefined;
    if (body?.method === "tools/call") requestedTools.push(body.params?.name ?? "");
  });
  registerMcp(app);
  const address = await app.listen({ host: "127.0.0.1", port: 0 });
  const samples = abilities.map(({ mcp }) => ({ tool: mcp.tool, checkArgs: mcp.checkArgs, input: z.toJSONSchema(mcp.input, { io: "input" }) }));

  // Only replace the child process's site manifest. The CLI, SDK, HTTP route and public reads are
  // unchanged, and use this file's empty test database; no real site module is needed for the fixture.
  function check(tools = samples) {
    const manifest = [{ name: "check-fixture", agent: { abilities: tools.map((mcp) => ({ mcp })) } }];
    const source = `
      import { z } from ${JSON.stringify(import.meta.resolve("zod"))};
      const asyncInput = ${asyncInput.toString()};
      export const SERVER_MODULES = ${JSON.stringify(manifest)};
      for (const module of SERVER_MODULES) for (const ability of module.agent.abilities) {
        // JSON Schema cannot carry refinements: use the same async schemas as the server.
        ability.mcp.input = ability.mcp.tool === "status_check" ? asyncInput(true)
          : ability.mcp.tool === "async_check" ? asyncInput(false) : z.fromJSONSchema(ability.mcp.input);
      }
    `;
    const preload = `
      import { registerHooks } from "node:module";
      const manifestUrl = ${JSON.stringify(import.meta.resolve("@aihot/site/modules/server"))};
      registerHooks({ load(url, context, next) {
        return url === manifestUrl ? { format: "module", source: ${JSON.stringify(source)}, shortCircuit: true } : next(url, context);
      } });
    `;
    return promisify(execFile)(process.execPath, ["--import", `data:text/javascript,${encodeURIComponent(preload)}`, "scripts/mcp-check.ts", `${address}/api/mcp`], {
      cwd: new URL("..", import.meta.url), encoding: "utf8", timeout: 15000,
    });
  }

  async function fails(tools: typeof samples, message: RegExp) {
    await assert.rejects(check(tools), (error: unknown) => {
      const result = error as Error & { code: number; stdout: string };
      assert.notEqual(result.code, 0);
      assert.match(result.stdout + result.message, message);
      return true;
    });
  }

  try {
    await t.test("a required sample and the default empty arguments both succeed", async () => {
      assert.match((await check()).stdout, /MCP contract check passed/);
      assert.deepEqual(calls, [{ label: "sample" }, {}]);
    });
    await t.test("a required tool without a sample is discovered without a false failure", async () => {
      const before = requestedTools.length;
      const result = await check(samples.map((sample) => ({ ...sample, checkArgs: undefined })));
      assert.match(result.stdout, /echo_check → discovery only/);
      assert.match(result.stdout, /MCP contract check passed/);
      const moduleCalls = requestedTools.slice(before).filter((name) => samples.some((sample) => name === mcpToolName(sample.tool)));
      assert.deepEqual(moduleCalls, [mcpToolName("status_check")]);
    });
    await t.test("async input validation decides empty calls and preserves explicit samples", async () => {
      const before = requestedTools.length;
      const result = await check();
      assert.match(result.stdout, /status_check \{\} → ok/);
      assert.match(result.stdout, /async_check → discovery only/);
      const moduleCalls = requestedTools.slice(before).filter((name) => samples.some((sample) => name === mcpToolName(sample.tool)));
      assert.deepEqual(moduleCalls, [mcpToolName("echo_check"), mcpToolName("status_check")]);
      assert.match((await check([samples[0], samples[1], { ...samples[2], checkArgs: { id: "sample" } }])).stdout, /async_check \{"id":"sample"\} → ok/);
      assert.deepEqual(calls.at(-1), { id: "sample" });
    });
    await t.test("an explicit invalid sample still fails SDK validation", async () => {
      await fails([{ ...samples[0], checkArgs: {} }, samples[1], samples[2]], /expected success, got an error/);
    });
    await t.test("schema-valid arguments do not excuse a failed read", async () => {
      await fails([{ ...samples[0], checkArgs: { label: "fail" } }, samples[1], samples[2]], /expected success, got an error/);
    });
    await t.test("every declared module tool must be listed", async () => {
      await fails([...samples, { ...samples[0], tool: "missing_check", checkArgs: undefined }], /tool list mismatch/);
    });
  } finally {
    app.server.closeAllConnections();
    await app.close();
    installModules([]);
    await closeDb();
  }
});

// MCP answers only requests addressed to this site (SITE_URL, MCP_ALLOWED_HOSTS and localhost): the Host,
// or the forwarded host, is parsed whole (one host and an optional port). Failure cases: an IPv6 host
// with a port ([::1]:3001) cut at its first colon and refused; a port that is not a port (localhost:abc,
// localhost:80:90) passing as localhost; a request naming its host twice judged by Node's first value;
// X-Forwarded-Host losing its precedence over Host; an extra host allowed in a spelling nobody configured.
import "./setup.ts";
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { request } from "node:http";
import { after, test } from "node:test";
import { promisify } from "node:util";
import Fastify from "fastify";
import { config } from "@aihot/backend/config";
import { registerMcp } from "../apps/api/src/routes/mcp.ts";

const initialize = {
  jsonrpc: "2.0", id: 1, method: "initialize",
  params: { protocolVersion: "2025-03-26", capabilities: {}, clientInfo: { name: "host-test", version: "1.0.0" } },
};

const SITE = new URL(config.siteUrl).hostname;
const app = Fastify();
registerMcp(app);
after(() => app.close());

function post(headers: Record<string, string | string[]>) {
  return app.inject({
    method: "POST", url: "/api/mcp", payload: initialize,
    headers: { "content-type": "application/json", accept: "application/json, text/event-stream", ...headers },
  });
}

function assertDenied(response: Awaited<ReturnType<typeof post>>, status = 421) {
  assert.equal(response.statusCode, status, response.body);
  assert.deepEqual(response.json(), { error: status === 421 ? "misdirected_request" : "origin_not_allowed" });
  assert.equal(response.headers["cache-control"], "no-store");
  assert.equal(response.headers["access-control-allow-origin"], undefined);
}

test("MCP initializes through each of its hosts, with or without a port", async () => {
  const requests: Array<Record<string, string>> = [
    { host: SITE },
    { host: `${SITE.toUpperCase()}:443` },
    { host: "localhost" },
    { host: "LOCALHOST:65535" },
    { host: "127.0.0.1" },
    { host: "127.0.0.1:3001" },
    { host: "[::1]" },
    { host: "[::1]:0" },
    { host: "[::1]:00080" },
    { host: "[::1]:3001" },
    { host: "[0:0:0:0:0:0:0:1]:3001" },
    { host: "127.0.0.1:3001", "x-forwarded-host": "[::1]:3000" },
  ];
  for (const headers of requests) {
    const response = await post(headers);
    assert.equal(response.statusCode, 200, `${JSON.stringify(headers)}: ${response.body}`);
    const body = response.headers["content-type"]?.startsWith("text/event-stream")
      ? JSON.parse(response.body.split("\n").find((line) => line.startsWith("data: "))!.slice(6))
      : response.json();
    assert.equal(body.id, 1);
    assert.equal(body.result.protocolVersion, "2025-03-26");
    assert.equal(response.headers["cache-control"], "no-store");
  }
});

test("MCP refuses malformed or other Host and forwarded authorities", async () => {
  const authorities = [
    "", "evil.invalid", "localhost.", "127.0.0.1.", `${SITE}.`, `evil.${SITE}`, `${SITE}.evil.invalid`,
    "127.1", "2130706433", "0x7f000001", "0177.0.0.1",
    "evil@localhost", "localhost@evil.invalid", "localhost/path", "localhost?query", " localhost", "localhost\t", "localhost\0",
    "localhost,evil.invalid", "::1", "[::1", "[::1]extra", "[::g]", "[]", "%6cocalhost", "http://localhost",
    "localhost:", "localhost:-1", "localhost:abc", "localhost:65536", "localhost:80:90", "[::1]:", "[::1]:abc",
  ];
  for (const authority of authorities) {
    const requests: Array<Record<string, string>> = [{ host: "localhost", "x-forwarded-host": authority }];
    if (authority) requests.push({ host: authority });
    for (const headers of requests) {
      const response = await post(headers);
      assert.equal(response.statusCode, 421, `${JSON.stringify(headers)}: ${response.body}`);
      assertDenied(response);
    }
  }
  for (const authority of [["localhost", "evil.invalid"], ["[::1]", "localhost"], []]) {
    assertDenied(await post({ host: "localhost", "x-forwarded-host": authority }));
  }
});

/** A request sent with exactly these header fields: the injector would merge a repeated Host or fill in an empty one. */
function rawRequest(address: string, fields: string[]) {
  return new Promise<{ status: number | undefined; body: string; cache: string | undefined }>((resolve, reject) => {
    const req = request(`${address}/api/mcp`, {
      method: "POST", setHost: false, headers: [...fields, "Content-Type", "application/json", "Accept", "application/json, text/event-stream"],
    }, (res) => {
      let body = "";
      res.setEncoding("utf8");
      res.on("data", (chunk) => { body += chunk; });
      res.on("end", () => resolve({ status: res.statusCode, body, cache: res.headers["cache-control"] }));
      res.on("error", reject);
    });
    req.on("error", reject);
    req.end(JSON.stringify(initialize));
  });
}

test("MCP refuses an empty Host and a host named twice", async () => {
  const server = Fastify();
  registerMcp(server);
  try {
    const address = await server.listen({ host: "127.0.0.1", port: 0 });
    for (const fields of [
      ["Host", ""],
      ["Host", "[::1]", "Host", "evil.invalid"],
      ["Host", "localhost", "Host", "localhost"],
      ["Host", "localhost", "hOsT", "evil.invalid"],
      ["Host", "evil.invalid", "Host", "localhost"],
      ["Host", "localhost", "X-Forwarded-Host", "[::1]", "X-Forwarded-Host", "[::1]"],
      ["Host", "localhost", "X-Forwarded-Host", "[::1]", "x-forwarded-host", "evil.invalid"],
    ]) {
      const response = await rawRequest(address, fields);
      assert.equal(response.status, 421, `${JSON.stringify(fields)}: ${response.body}`);
      assert.deepEqual(JSON.parse(response.body), { error: "misdirected_request" });
      assert.equal(response.cache, "no-store");
    }
    // The forwarded host decides when there is one, so the Host fields behind it do not matter.
    const forwarded = await rawRequest(address, ["Host", "evil.invalid", "Host", "localhost", "X-Forwarded-Host", "[::1]"]);
    assert.equal(forwarded.status, 200, forwarded.body);
  } finally {
    await server.close();
  }
});

test("an IPv6 host gets the same Origin answers as IPv4, and GET and DELETE check the Host too", async () => {
  for (const host of ["127.0.0.1:3001", "[::1]:3001"]) {
