  assert.ok(ttl <= 60, `an aged response must not restart its TTL: ${cached.headers["cache-control"]}`);
  t.mock.timers.tick(61_000);
  const refreshed = await app.inject("/sitemap.xml");
  assert.equal(refreshed.statusCode, 200);
